    for (size_t k = 0; k < N; ++k) {
        // Compute U[k][k:] using A[k][k:] and L[k][:k] * U[:k][k:]
        double sum = 0.0;
        for (size_t m = 0; m < k; ++m) {
            sum += L[k * N + m] * U[m * N + k];
        }
        U[k * N + k] = denseA[k * N + k] - sum;

        // Compute remaining elements in row k of U
        for (size_t j = k + 1; j < N; ++j) {
            sum = 0.0;
            for (size_t m = 0; m < k; ++m) {
                sum += L[k * N + m] * U[m * N + j];
            }
            U[k * N + j] = denseA[k * N + j] - sum;
        }

        // Compute remaining elements in column k of L
        for (size_t i = k + 1; i < N; ++i) {
            sum = 0.0;
            for (size_t m = 0; m < k; ++m) {
                sum += L[i * N + m] * U[m * N + k];
            }
            L[i * N + k] = (denseA[i * N + k] - sum) / U[k * N + k];
        }
    }
}

void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
    std::vector<std::vector<double>> matrix(N, std::vector<double>(N, 0.0));
    for (auto &elem : A) {
        matrix[elem.row][elem.column] = elem.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    for (size_t i = 0; i < N; ++i) {
        L[i * N + i] = 1.0;
    }

    for (size_t i = 0; i < N; ++i) {
        for (size_t k = i; k < N; ++k) {
            double sum = 0.0;
            for (size_t j = 0; j < i; ++j) {
                sum += L[i * N + j] * U[j * N + k];
            }
            U[i * N + k] = matrix[i][k] - sum;
        }

        for (size_t k = i; k < N; ++k) {
            if (i == k) continue;
            double sum = 0.0;
            for (size_t j = 0; j < i; ++j) {
                sum += L[k * N + j] * U[j * N + i];
            }
            L[k * N + i] = (matrix[k][i] - sum) / U[i * N + i];
        }
    }
}

